1	export type Customer = { yearsWithMHPCO: number };
2	
3	export type Scenario = {
4	  customer: Customer;
5	  steps: Step[];
6	};
7	
8	export type Step =
9	  | { op: "quote"; items: Item[] }
10	  | { op: "claim"; policy: number; incident: Incident };
11	
12	export type Item = {
13	  type: string;
14	  material?: string;
15	  enchantment?: number;
16	  cursed?: boolean;
17	};
18	
19	export type Incident = {
20	  cause: string;
21	  damages: Damage[];
22	};
23	
24	export type Damage = {
25	  itemType: string;
26	  amount: number;
27	};
28	
29	export type Result = { premium: number } | { payout: number; remainingCap: number };
30	
31	const PROCESSING_FEE = 5;
32	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
33	
34	// The catalogue of insurable item types. Each type carries both figures the
35	// office needs: what it costs to insure (base premium) and what it is worth
36	// when destroyed (insurance value). Keeping them in one row means a new item
37	// type is one edit, and the two figures can never drift apart.
38	const CATALOGUE: Record<string, { basePremium: number; insuranceValue: number }> = {
39	  sword: { basePremium: 100, insuranceValue: 1000 },
40	  amulet: { basePremium: 60, insuranceValue: 600 },
41	  staff: { basePremium: 80, insuranceValue: 800 },
42	  potion: { basePremium: 40, insuranceValue: 400 },
43	  rune: { basePremium: 25, insuranceValue: 250 },
44	  moonstone: { basePremium: 25, insuranceValue: 250 },
45	};
46	
47	// Both catalogue figures are read through this one row lookup, so an item's type
48	// is resolved against the catalogue in exactly one place — which makes it also
49	// the one place that can tell an insurable type from an uninsurable one. The
50	// catalogue does not merely price the types the MHPCO insures; it DEFINES them,
51	// so a missing row is not a lookup miss to defend against but the office
52	// declining the item, and it is reported in those terms.
53	const catalogueEntryFor = (item: Item) => {
54	  const entry = CATALOGUE[item.type];
55	  if (entry === undefined) {
56	    throw new Error(`the MHPCO does not insure items of type "${item.type}"`);
57	  }
58	  return entry;
59	};
60	
61	// Totalling a catalogue column over a list of items is the same operation on the
62	// premium side and the claim side; only the column differs. Naming it once keeps
63	// the two columns visibly separate — which is the point: the building-block
64	// discount rewrites the basePremium column and never touches insuranceValue.
65	const totalOfColumn =
66	  (columnOf: (item: Item) => number) =>
67	  (items: Item[]): number =>
68	    items.reduce((total, item) => total + columnOf(item), 0);
69	
70	const basePremiumOf = (item: Item): number => catalogueEntryFor(item).basePremium;
71	
72	const BLOCK_SIZE = 3;
73	const BLOCK_BASE_PREMIUM = 60;
74	
75	const formsABuildingBlock = (alikeItems: Item[]): boolean =>
76	  alikeItems.length === BLOCK_SIZE;
77	
78	const sumOfBasePremiums = totalOfColumn(basePremiumOf);
79	
80	const CURSE_SURCHARGE_RATE = 0.5;
81	const HIGH_ENCHANTMENT_LEVEL = 5;
82	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
83	
84	const isCursed = (item: Item): boolean => item.cursed === true;
85	
86	// An unenchanted item is enchantment 0, so every threshold reads the level the
87	// same way. The MHPCO sets several enchantment thresholds for different rules;
88	// each names its own level and compares through here.
89	const enchantmentLevelOf = (item: Item): number => item.enchantment ?? 0;
90	
91	const carriesEnchantmentSurcharge = (item: Item): boolean =>
92	  enchantmentLevelOf(item) >= HIGH_ENCHANTMENT_LEVEL;
93	
94	// A rate table prices one subject: every row whose risk applies contributes its
95	// rate, and the total is their sum. Both the item surcharges and the policy-wide
96	// modifiers are rate tables — they differ only in what they are applied to.
97	type RateTable<Subject> = { appliesTo: (subject: Subject) => boolean; rate: number }[];
98	
99	const totalRateFrom = <Subject,>(table: RateTable<Subject>, subject: Subject): number =>
100	  table.reduce((total, row) => (row.appliesTo(subject) ? total + row.rate : total), 0);
101	
102	// Every item-specific surcharge is a rate on THAT item's base premium, charged
103	// when its risk applies. Adding a new one means adding a row here — nothing else.
104	const ITEM_SURCHARGES: RateTable<Item> = [
105	  { appliesTo: isCursed, rate: CURSE_SURCHARGE_RATE },
106	  { appliesTo: carriesEnchantmentSurcharge, rate: HIGH_ENCHANTMENT_SURCHARGE_RATE },
107	];
108	
109	const surchargeRateOn = (item: Item): number => totalRateFrom(ITEM_SURCHARGES, item);
110	
111	const itemSurchargesOn = (items: Item[]): number =>
112	  items.reduce((sum, item) => sum + basePremiumOf(item) * surchargeRateOn(item), 0);
113	
114	// Items of the same type are "alike"; each group is priced together so a
115	// building block can be recognised.
116	const alikeItemGroupsIn = (items: Item[]): Item[][] => [
117	  ...items
118	    .reduce(
119	      (groups, item) => groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
120	      new Map<string, Item[]>(),
121	    )
122	    .values(),
123	];
124	
125	const basePremiumOfAlikeItems = (alikeItems: Item[]): number =>
126	  formsABuildingBlock(alikeItems) ? BLOCK_BASE_PREMIUM : sumOfBasePremiums(alikeItems);
127	
128	const policyBaseOf = (items: Item[]): number =>
129	  alikeItemGroupsIn(items).reduce(
130	    (sum, alikeItems) => sum + basePremiumOfAlikeItems(alikeItems),
131	    0,
132	  );
133	
134	// Rounding always favours the MHPCO. Which direction that is follows from which
135	// way the money moves: an amount the office RECEIVES is rounded up, an amount it
136	// PAYS is rounded down. Naming the two directions makes the rule one concept
137	// rather than two opposite-looking halves, and each call site says which kind of
138	// amount it holds — so the reason for the direction is in the code, not a comment.
139	const settledAsReceived = Math.ceil;
140	const settledAsPaid = Math.floor;
141	
142	const LOYALTY_YEARS = 2;
143	const LOYALTY_DISCOUNT_RATE = -0.2;
144	
145	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = -0.15;
146	
147	// Each item in a quote is treated as a first insurance regardless of customer
148	// history, so this surcharge is unconditional.
149	const appliesUnconditionally = (): boolean => true;
150	
151	const isLongStanding = ({ customer }: QuoteContext): boolean =>
152	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
153	
154	const isFollowUpContract = ({ precedingQuotes }: QuoteContext): boolean =>
155	  precedingQuotes > 0;
156	
157	// A quote is priced from the customer plus its place in the scenario's history.
158	type QuoteContext = { customer: Customer; precedingQuotes: number };
159	
160	// Every policy-wide modifier is a rate on the UNMODIFIED policy base — never on a
161	// base that already includes the item surcharges. Surcharges carry a positive
162	// rate, discounts a negative one. Adding a new one means adding a row here.
163	const POLICY_MODIFIERS: RateTable<QuoteContext> = [
164	  { appliesTo: appliesUnconditionally, rate: FIRST_INSURANCE_SURCHARGE_RATE },
165	  { appliesTo: isLongStanding, rate: LOYALTY_DISCOUNT_RATE },
166	  { appliesTo: isFollowUpContract, rate: FOLLOW_UP_CONTRACT_DISCOUNT_RATE },
167	];
168	
169	const policyModifiersOn = (policyBase: number, context: QuoteContext): number =>
170	  policyBase * totalRateFrom(POLICY_MODIFIERS, context);
171	
172	const quoteFor = (items: Item[], context: QuoteContext): Result => {
173	  const policyBase = policyBaseOf(items);
174	  const riskAdjustedBase = policyBase + itemSurchargesOn(items);
175	  return {
176	    premium: settledAsReceived(
177	      riskAdjustedBase + policyModifiersOn(policyBase, context) + PROCESSING_FEE,
178	    ),
179	  };
180	};
181	
182	const DEDUCTIBLE_PER_DAMAGE = 100;
183	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
184	
185	const insuranceValueOf = (item: Item): number => catalogueEntryFor(item).insuranceValue;
186	
187	// The insurance sum totals the value column over every insured item — one item,
188	// one row, no grouping. Blocks are a premium concept and cannot reach it.
189	const insuranceSumOf = totalOfColumn(insuranceValueOf);
190	
191	// A policy created by a quote step, tracked by that step's index so later claims
192	// can find it and draw down its cap.
193	type Policy = { items: Item[]; remainingCap: number };
194	
195	const policyFor = (items: Item[]): Policy => ({
196	  items,
197	  remainingCap: insuranceSumOf(items) * CAP_MULTIPLE_OF_INSURANCE_SUM,
198	});
199	
200	const HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL = 8;
201	const HALF_REIMBURSEMENT_RATE = 0.5;
202	const FULL_REIMBURSEMENT_RATE = 1;
203	
204	// A distinct rule from the premium's HIGH_ENCHANTMENT_LEVEL, at a distinct
205	// level: this one halves what a claim pays out, that one raises what a policy
206	// costs. They move independently — deliberately not shared.
207	const reimbursesOnlyHalf = (item: Item): boolean =>
208	  enchantmentLevelOf(item) >= HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL;
209	
210	// How much of the damage the MHPCO reimburses, before the deductible bites.
211	const reimbursementRateFor = (item: Item): number =>
212	  reimbursesOnlyHalf(item) ? HALF_REIMBURSEMENT_RATE : FULL_REIMBURSEMENT_RATE;
213	
214	// A damage names only an item TYPE, so it can identify no more than the type of
215	// the item it refers to; this returns the first insured item of that type as the
216	// representative whose traits price the damage.
217	//
218	// UNTESTED ASSUMPTION: that the first match is the right representative. Where a
219	// policy holds several alike items, the suite never distinguishes them — its only
220	// two-alike-items example insures two IDENTICAL swords, so first-match is
221	// unobservable there, and the spec offers no example pairing one type with
222	// DIFFERING enchantment or material. So this is an assumption the tests permit,
223	// not one they confirm. Should such an example appear, the damage would have to
224	// be matched to a specific item and this would be the place that changes.
225	const insuredItemOfType = (policy: Policy, damage: Damage): Item => {
226	  const insured = policy.items.find((item) => item.type === damage.itemType);
227	  if (insured === undefined) {
228	    throw new Error(`the policy does not cover an item of type "${damage.itemType}"`);
229	  }
230	  return insured;
231	};
232	
233	const reimbursedAmountFor = (damage: Damage, policy: Policy): number =>
234	  damage.amount * reimbursementRateFor(insuredItemOfType(policy, damage));
235	
236	// The deductible bites once per damage, after the reimbursement rate is applied
237	// — never the other way round, which would pay out more.
238	const payoutForDamage = (damage: Damage, policy: Policy): number =>
239	  reimbursedAmountFor(damage, policy) - DEDUCTIBLE_PER_DAMAGE;
240	
241	// One incident can damage several items; each damage is settled on its own
242	// (and so bears its own deductible), and the incident pays out their sum.
243	const payoutForIncident = (incident: Incident, policy: Policy): number =>
244	  incident.damages.reduce((sum, damage) => sum + payoutForDamage(damage, policy), 0);
245	
246	// A payout is drawn from the policy's cap, leaving less for later claims.
247	const capDrawnDownBy = (policy: Policy, payout: number): Policy => ({
248	  ...policy,
249	  remainingCap: policy.remainingCap - payout,
250	});
251	
252	// The policy pays no more than the cap it has left, however large the damage.
253	const payoutWithinCapOf = (policy: Policy, desiredPayout: number): number =>
254	  Math.min(desiredPayout, policy.remainingCap);
255	
256	// Settling a claim pays out and draws the cap down by the same amount, so the
257	// result the customer sees is the payout plus the cap that payout left behind.
258	const claimFor = (incident: Incident, policy: Policy): [Result, Policy] => {
259	  const payout = settledAsPaid(
260	    payoutWithinCapOf(policy, payoutForIncident(incident, policy)),
261	  );
262	  const settledPolicy = capDrawnDownBy(policy, payout);
263	  return [{ payout, remainingCap: settledPolicy.remainingCap }, settledPolicy];
264	};
265	
266	// What the scenario has accumulated before the current step: the results so far,
267	// the history a quote is priced against, and the policies earlier quotes created.
268	type ScenarioState = {
269	  results: Result[];
270	  precedingQuotes: number;
271	  policies: Record<number, Policy>;
272	};
273	
274	const INITIAL_SCENARIO_STATE: ScenarioState = {
275	  results: [],
276	  precedingQuotes: 0,
277	  policies: {},
278	};
279	
280	// Every step reports exactly one result and leaves one policy at its index —
281	// the two things both step kinds always do. Recording them is named once here
282	// rather than rebuilt in each of them.
283	const withStepRecorded = (
284	  state: ScenarioState,
285	  result: Result,
286	  policyIndex: number,
287	  policy: Policy,
288	): ScenarioState => ({
289	  ...state,
290	  results: [...state.results, result],
291	  policies: { ...state.policies, [policyIndex]: policy },
292	});
293	
294	const afterQuote = (
295	  state: ScenarioState,
296	  items: Item[],
297	  customer: Customer,
298	  stepIndex: number,
299	): ScenarioState => ({
300	  ...withStepRecorded(
301	    state,
302	    quoteFor(items, { customer, precedingQuotes: state.precedingQuotes }),
303	    stepIndex,
304	    policyFor(items),
305	  ),
306	  precedingQuotes: state.precedingQuotes + 1,
307	});
308	
309	const afterClaim = (
310	  state: ScenarioState,
311	  policyIndex: number,
312	  incident: Incident,
313	): ScenarioState => {
314	  const [result, settledPolicy] = claimFor(incident, state.policies[policyIndex]);
315	  return withStepRecorded(state, result, policyIndex, settledPolicy);
316	};
317	
318	const afterStep = (
319	  state: ScenarioState,
320	  step: Step,
321	  customer: Customer,
322	  stepIndex: number,
323	): ScenarioState =>
324	  step.op === "quote"
325	    ? afterQuote(state, step.items, customer, stepIndex)
326	    : afterClaim(state, step.policy, step.incident);
327	
328	export const runScenario = (scenario: Scenario): { results: Result[] } => {
329	  const { results } = scenario.steps.reduce(
330	    (state, step, stepIndex) => afterStep(state, step, scenario.customer, stepIndex),
331	    INITIAL_SCENARIO_STATE,
332	  );
333	  return { results };
334	};
