// A claim names the quote step whose policy it draws on. Only a quote creates a
// policy, so an index no quote reached is the claim naming a policy that does not
// exist — the third and last of this file's lookups that can miss, reported like
// the other two: a domain error naming the offender, not a TypeError from the
// first field the missing policy is asked for.
const policyAt = (state: ScenarioState, policyIndex: number): Policy => {
  const policy = state.policies[policyIndex];
  if (policy === undefined) {
    throw new Error(`there is no policy at step ${policyIndex}`);
  }
  return policy;
};

const afterClaim = (
  state: ScenarioState,
  policyIndex: number,
  incident: Incident,
): ScenarioState => {
  const [result, settledPolicy] = claimFor(incident, policyAt(state, policyIndex));
  return withStepRecorded(state, result, policyIndex, settledPolicy);
};

